import csv
from datetime import datetime

# Night shift on 2026-09-09: starts 2026-09-09 22:00, ends 2026-09-10 06:00
rows = []
with open('/app/data/sensor_log.csv') as f:
    for r in csv.DictReader(f):
        ts = datetime.strptime(r['timestamp'], '%Y-%m-%d %H:%M')
        if ts >= datetime(2026,9,9,22,0) and ts < datetime(2026,9,10,6,0):
            rows.append(r)

down = {}
machines = set()
for r in rows:
    machines.add(r['machine_id'])
    if r['state'] == 'DOWN':
        down[r['machine_id']] = down.get(r['machine_id'], 0) + 1

dt = {m: down.get(m,0) for m in sorted(machines)}
limit = 45
over = sorted([m for m,v in dt.items() if v > limit])
print(dt, limit, over)
EOF"}

