import csv, json
limit=30
down={}
machines=set()
for r in csv.DictReader(open('data/sensor_log.csv')):
    machines.add(r['machine_id'])
    ts=r['timestamp']; m=r['machine_id']
    d=ts.split(' ')[0]; hm=ts.split(' ')[1]
    # night shift starting 2026-09-09 covers 09-09 22:00 to 09-10 06:00
    if d=='2026-09-09' and hm>='22:00':
        inc=True
    elif d=='2026-09-10' and hm<'06:00':
        inc=True
    else:
        inc=False
    if inc and r['state']=='DOWN':
        down[m]=down.get(m,0)+1
result={m:down.get(m,0) for m in sorted(machines)}
over=[m for m in sorted(machines) if result[m]>limit]
json.dump({'limit_min':limit,'downtime_by_machine':result,'over_limit':over},open('output/downtime.json','w'),indent=2)
print(result); print(over)
""}

