{"type": "run_bash", "command": "cd /app && python3 - <<'EOF'
import csv, json
from collections import defaultdict
from datetime import datetime

LIMIT=40
rows=[]
with open('data/sensor_log.csv') as f:
    r=csv.DictReader(f)
    for row in r:
        rows.append((row['timestamp'],row['machine_id'],row['state']))
rows.sort(key=lambda x:(x[1],x[0]))

machines=sorted(set(x[1] for x in rows))

# per machine, collect contiguous DOWN runs restricted to window
prev_state={}
cur_len={}
final_runs=defaultdict(list)

for ts,mid,state in rows:
    inwin = ('2026-09-10 14:00' <= ts < '2026-09-10 22:00')
    if mid not in cur_len:
        cur_len[mid]=0
        prev_state[mid]=None
    if inwin and state=="DOWN":
        if prev_state[mid]=="DOWN":
            cur_len[mid]+=1
        else:
            cur_len[mid]=1
    else:
        if prev_state[mid]=="DOWN":
            final_runs[mid].append(cur_len[mid])
            cur_len[mid]=0
    if inwin:
        prev_state[mid]=state
    else:
        prev_state[mid]=None
for mid in machines:
    if prev_state[mid]=="DOWN" and cur_len[mid]>0:
        final_runs[mid].append(cur_len[mid])

result=defaultdict(int)
for mid in machines:
    for ln in final_runs[mid]:
        if ln>=3:
            result[mid]+=ln

over=sorted([m for m in machines if result[m]>LIMIT])
out={"limit_min":LIMIT,"downtime_by_machine":{m:result[m] for m in machines},"over_limit":over}
print(json.dumps(out,indent=2))
with open('output/downtime.json','w') as f:
    json.dump(out,f,indent=2)

# debug: show raw DOWN minute counts and run distributions
raw=defaultdict(int)
for ts,mid,state in rows:
    if ('2026-09-10 14:00' <= ts < '2026-09-10 22:00') and state=="DOWN":
        raw[mid]+=1
print('raw DOWN minutes:', {m:raw[m] for m in machines})
EOF", "metadata": {}}

