for r in rows:
    by_machine.setdefault(r['machine_id'], []).append(r)

def parse_ts(ts):
    return datetime.strptime(ts, '%Y-%m-%d %H:%M')

# night shift starting 2026-09-09: 2026-09-09 22:00 to 2026-09-10 06:00
start = parse_ts('2026-09-09 22:00')
end = parse_ts('2026-09-10 06:00')

def in_shift(ts):
    return start <= ts < end

result = {}
for m, rs in sorted(by_machine.items()):
    rs = sorted(rs, key=lambda r: parse_ts(r['timestamp']))
    total = 0
    # build consecutive DOWN runs within the night shift window
    run_start = None
    for r in rs:
        ts = parse_ts(r['timestamp'])
        st = r['state']
        inwin = in_shift(ts)
        if inwin and st in down_states:
            if run_start is None:
                run_start = ts
        else:
            # potential end of a run; but a run could continue outside window? we only count within window
            if run_start is not None:
                endts = ts  # this minute is not DOWN-in-window, so previous minute (ts - 1min) was last DOWN in window
                # compute duration of the run in window, clipped to [start,end)
                rstart = max(run_start, start)
                rend = min(endts, end)  # endts is first minute not DOWN-in-window, i.e., last down minute + 1 min
                if rend > rstart:
                    total += int((rend - rstart).total_seconds() // 60)
                run_start = None
    # flush
    if run_start is not None:
        rstart = max(run_start, start)
        rend = min(end, end)
        if rend > rstart:
            total += int((rend - rstart).total_seconds() // 60)
    # exclude micro-stops < 5 minutes: need to recompute runs, skipping runs <5 min
    result[m] = total

print(json.dumps(result, indent=2))
