import csv, json, os
from decimal import Decimal, ROUND_HALF_UP

# Load FX rates
fx = {}
with open('/app/finance/fx_rates.csv') as f:
    for row in csv.DictReader(f):
        fx[(row['date'], row['currency'])] = Decimal(row['eur_per_unit'])

# Apply corrections
fx[('2026-07-04','GBP')] = Decimal('1.2176')
fx[('2026-08-14','JPY')] = Decimal('0.005769')
fx[('2026-08-15','USD')] = Decimal('0.8446')

# City tiers: base
# Tier A: Berlin, Geneva, London, New York, Paris, Tokyo, Zurich
# Tier B: Austin, Lisbon, Madrid, Manchester, Osaka
# After amendment 23 (effective 2026-08-13): Austin is Tier A
tier_a_base = {'Berlin','Geneva','London','New York','Paris','Tokyo','Zurich'}
tier_b_base = {'Austin','Lisbon','Madrid','Manchester','Osaka'}

def get_tier(city, date_str):
    if city == 'Austin' and date_str >= '2026-08-13':
        return 'A'
    if city in tier_a_base:
        return 'A'
    if city in tier_b_base:
        return 'B'
    return 'B'  # default

# Lodging cap for Tier A:
# base: 220
# amendment 22 (2026-08-10): 235
# amendment 24 (2026-08-14): 245
def get_lodging_cap_tier_a(date_str):
    if date_str >= '2026-08-14':
        return Decimal('245')
    if date_str >= '2026-08-10':
        return Decimal('235')
    return Decimal('220')

# All other caps are static
CAPS = {
    ('meals','A'): Decimal('60'),
    ('meals','B'): Decimal('40'),
    ('taxi','A'): Decimal('50'),
    ('taxi','B'): Decimal('50'),
}

def get_cap(category, tier, date_str):
    if category == 'lodging':
        if tier == 'A':
            return get_lodging_cap_tier_a(date_str)
        else:
            return Decimal('140')
    elif category == 'flights':
        return None  # no cap
    else:
        return CAPS.get((category, tier), Decimal('0'))

# Load employees
employees = {}
dep_map = {}
with open('/app/data/employees.csv') as f:
    for row in csv.DictReader(f):
        employees[row['employee_id']] = row
        if row['department'] == 'Operations':
            dep_map[row['employee_id']] = True

# Load claims and process
violations = []
by_employee = {}
reimbursable_eur = Decimal('0')

with open('/app/data/claims.csv') as f:
    for row in csv.DictReader(f):
        emp = row['employee_id']
        date_str = row['date']
        city = row['city']
        category = row['category']
        amount = Decimal(row['amount'])
        currency = row['currency']
        receipt = row['receipt'].strip().lower()
        approval_id = row['approval_id'].strip()
        claim_id = row['claim_id']

        # Filter: Operations dept, August 2026
        if emp not in dep_map:
            continue
        if not (date_str >= '2026-08-01' and date_str <= '2026-08-31'):
            continue

        # Convert to EUR and round to 2 decimals
        if currency == 'EUR':
            eur_amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        else:
            rate = fx.get((date_str, currency))
            if rate is None:
                print(f"WARNING: no FX rate for {date_str} {currency} (claim {claim_id})")
                rate = Decimal('1')
            eur_amount = (amount * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Determine policy violation
        is_violation = False
        reimbursable = eur_amount

        # Rule: Flights need approval_id
        if category == 'flights':
            if not approval_id:
                is_violation = True
                reimbursable = Decimal('0')
        else:
            # Rule: Receipts required for claims above 40 EUR
            if eur_amount > Decimal('40') and receipt != 'yes':
                is_violation = True
                reimbursable = Decimal('0')
            else:
                # Rule: Cap check
                tier = get_tier(city, date_str)
                cap = get_cap(category, tier, date_str)
                if cap is not None and eur_amount > cap:
                    is_violation = True
                    reimbursable = cap

        if is_violation:
            violations.append(claim_id)

        by_employee[emp] = by_employee.get(emp, Decimal('0')) + reimbursable
        reimbursable_eur += reimbursable

# Round to 2 decimals
by_employee_out = {k: float(v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)) for k, v in sorted(by_employee.items())}
reimbursable_out = float(reimbursable_eur.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

result = {
    "violations": sorted(violations),
    "by_employee": by_employee_out,
    "reimbursable_eur": reimbursable_out
}

os.makedirs('/app/output', exist_ok=True)
with open('/app/output/expense_report.json', 'w') as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))
