import json, csv, itertools, math

R=6371.0
def to_xy(lat,lon):
    la,lo=math.radians(lat),math.radians(lon)
    return (math.cos(la)*math.cos(lo), math.cos(la)*math.sin(lo), math.sin(la))
def dist(a,b):
    A,B=to_xy(*a),to_xy(*b)
    d=math.degrees(math.acos(max(-1,min(1, A[0]*B[0]+A[1]*B[1]+A[2]*B[2]))))
    return d*R/1000.0

vans=json.load(open('data/vans.json'))
depot=tuple(vans['depot'])
speed=vans['speed_kmh']
svc=vans['service_minutes_per_stop']
def parse_t(s):
    h,m=s.split(':'); return int(h)*60+int(m)
dep_time=parse_t(vans['departure'])
orders={}
for r in csv.DictReader(open('data/orders.csv')):
    if r['order_id']=='C08': continue
    orders[r['order_id']]={'lat':float(r['lat']),'lon':float(r['lon']),'dem':float(r['demand_kg']),'ws':parse_t(r['window_start']),'we':parse_t(r['window_end'])}

cap={'V1':810,'V2':810}
ids=list(orders)
# all partitions of orders into V1 (must include C07) and V2
best=None
def route_dist(route):
    pts=[depot]+[ (orders[o]['lat'],orders[o]['lon']) for o in route]+[depot]
    return sum(dist(pts[i],pts[i+1]) for i in range(len(pts)-1))

# feasible route with time windows
def feasible(route,van):
    total=sum(orders[o]['dem'] for o in route)
    if total>cap[van]: return None
    t=dep_time
    pts=[depot]+[(orders[o]['lat'],orders[o]['lon']) for o in route]+[depot]
    for i,o in enumerate(route):
        d=dist(pts[i],pts[i+1]); t+=d/speed*60+svc
        # wait for window open
        if t<orders[o]['ws']: t=orders[o]['ws']
        # arrival is before service start... arrival time is t - svc? 
        arr=t-svc
        if arr>orders[o]['we']: return None
    return route_dist(route)

import itertools
allsets=[]
for k in range(0,len(ids)+1):
    for combo in itertools.combinations(ids,k):
        s=set(combo)
        if 'C07' not in s: continue  # C07 must be V1
        v1=sorted(s); v2=sorted(set(ids)-s)
        r1=feasible(v1,'V1'); r2=feasible(v2,'V2')
        if r1 is None or r2 is None: continue
        allsets.append((r1+r2,v1,v2))

for total,v1,v2 in allsets:
    # try permutations for each route to minimize distance while feasible
    bestpair=None
    for p1 in itertools.permutations(v1):
        for p2 in itertools.permutations(v2):
            r1=feasible(p1,'V1'); 
            if r1 is None: continue
            r2=feasible(p2,'V2')
            if r2 is None: continue
            tot=r1+r2
            if bestpair is None or tot<bestpair[0]:
                bestpair=(tot,list(p1),list(p2))
    if bestpair:
        if best is None or bestpair[0]<best[0]:
            best=bestpair

print(best)
if best:
    tot,v1,v2=best
    plan={'routes':{'V1':v1,'V2':v2},'total_km':round(tot,2)}
    json.dump(plan,open('output/plan.json','w'),indent=2)
    print(plan)
